private int
doshn(struct magic_set *ms, int clazz, int swap, int fd, off_t off, int num,
    size_t size, off_t fsize, int mach, int strtab, int *flags,
    uint16_t *notecount)
{
        Elf32_Shdr sh32;
        Elf64_Shdr sh64;
        int stripped = 1, has_debug_info = 0;
        size_t nbadcap = 0;
        void *nbuf;
        off_t noff, coff, name_off;
        uint64_t cap_hw1 = 0;   /* SunOS 5.x hardware capabilites */
        uint64_t cap_sf1 = 0;   /* SunOS 5.x software capabilites */
        char name[50];
        ssize_t namesize;

        if (size != xsh_sizeof) {
                if (file_printf(ms, ", corrupted section header size") == -1)
                        return -1;
                return 0;
        }

        /* Read offset of name section to be able to read section names later */
        if (pread(fd, xsh_addr, xsh_sizeof, CAST(off_t, (off + size * strtab)))
            < (ssize_t)xsh_sizeof) {
                if (file_printf(ms, ", missing section headers") == -1)
                        return -1;
                return 0;
        }
        name_off = xsh_offset;

        for ( ; num; num--) {
                /* Read the name of this section. */
                if ((namesize = pread(fd, name, sizeof(name) - 1, name_off + xsh_name)) == -1) {
                        file_badread(ms);
                        return -1;
                }
                name[namesize] = '\0';
                if (strcmp(name, ".debug_info") == 0) {
                        has_debug_info = 1;
                        stripped = 0;
                }

                if (pread(fd, xsh_addr, xsh_sizeof, off) < (ssize_t)xsh_sizeof) {
                        file_badread(ms);
                        return -1;
                }
                off += size;

                /* Things we can determine before we seek */
                switch (xsh_type) {
                case SHT_SYMTAB:
#if 0
                case SHT_DYNSYM:
#endif
                        stripped = 0;
                        break;
                default:
                        if (fsize != SIZE_UNKNOWN && xsh_offset > fsize) {
                                /* Perhaps warn here */
                                continue;
                        }
                        break;
                }


                /* Things we can determine when we seek */
                switch (xsh_type) {
                case SHT_NOTE:
                        if ((uintmax_t)(xsh_size + xsh_offset) >
                            (uintmax_t)fsize) {
                                if (file_printf(ms,
                                    ", note offset/size %#" INTMAX_T_FORMAT
                                    "x+%#" INTMAX_T_FORMAT "x exceeds"
                                    " file size %#" INTMAX_T_FORMAT "x",
                                    (uintmax_t)xsh_offset, (uintmax_t)xsh_size,
                                    (uintmax_t)fsize) == -1)
                                        return -1;
                                return 0;
                        }
                        if ((nbuf = malloc(xsh_size)) == NULL) {
                                file_error(ms, errno, "Cannot allocate memory"
                                    " for note");
                                return -1;
                        }
                        if (pread(fd, nbuf, xsh_size, xsh_offset) <
                            (ssize_t)xsh_size) {
                                file_badread(ms);
                                free(nbuf);
                                return -1;
                        }

                        noff = 0;
                        for (;;) {
                                if (noff >= (off_t)xsh_size)
                                        break;
                                noff = donote(ms, nbuf, (size_t)noff,
                                    xsh_size, clazz, swap, 4, flags, notecount,
                                    fd, 0, 0, 0);
                                if (noff == 0)
                                        break;
                        }
                        free(nbuf);
                        break;
                case SHT_SUNW_cap:
                        switch (mach) {
                        case EM_SPARC:
                        case EM_SPARCV9:
                        case EM_IA_64:
                        case EM_386:
                        case EM_AMD64:
                                break;
                        default:
                                goto skip;
                        }

